export function hasRoleAtLeast(role: Role, atLeast: Role): boolean {
  return ROLE_RANK[role] >= ROLE_RANK[atLeast];
}

/**
 * A person who can act in the workspace right now. Removal archives the row
 * and leaves `status` as it was, so both have to be checked: an archived
 * member is a former member, and an invited or suspended one is not current.
 */
export function isCurrentMember(
  member: Pick<Member, "status" | "archivedAt"> | null | undefined,
): boolean {
  return (
    member != null && member.status === "active" && member.archivedAt === null
  );
}

import {
  archivePatch,
  restorePatch,
  shouldFilterArchived,
} from "@/lib/soft-delete";

/**
 * Re-admits a former member on the same row. Historical columns (`createdAt`,
 * `lastSeenAt`) stay; the invitation supplies the role, inviter and join date,
 * and clearing `archivedAt` is what makes the membership current again.
 */
export async function reinstateMember(
  orgId: OrgId,
  memberId: MemberId,
  role: Role,
  invitedBy: UserId | null,
  joinedAt: IsoTimestamp,
): Promise<Member> {
  const row = getDb()
    .update(members)
    .set({
      ...restorePatch(),
      role,
      status: "active",
      invitedBy,
      joinedAt,
    })
    .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
    .returning()
    .get();

  if (!row) throw new Error(`Member ${memberId} not found in org ${orgId}`);
  return toMember(row);
}

