import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { subscribe } from "@/lib/event-bus";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { hashToken } from "@/lib/hash";
import { runMigrations } from "@/server/db/migrate";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as commentService from "@/server/services/comment-service";
import { buildDigest, listDigestRecipients } from "@/server/services/digest-service";
import * as invitationService from "@/server/services/invitation-service";
import * as issueService from "@/server/services/issue-service";
import * as memberService from "@/server/services/member-service";
import { notify } from "@/server/services/notification-service";
import * as projectService from "@/server/services/project-service";
import { registerUsageListeners } from "@/server/services/usage-service";
import * as usageRepo from "@/server/repositories/usage-repository";
import { toIsoTimestamp } from "@/types/common";

const dir = mkdtempSync(join(tmpdir(), "taskflow-check-"));
const path = join(dir, "taskflow.db");
process.env.TASKFLOW_DB_PATH = path;
await runMigrations(path);
registerUsageListeners();

const fails: string[] = [];
function check(name: string, cond: boolean, extra?: unknown) {
  if (!cond) fails.push(`${name} ${extra === undefined ? "" : JSON.stringify(extra)}`);
  else console.log("ok", name);
}

const owner = await userRepo.insertUser({
  email: "owner@a.test",
  name: "Owner",
  passwordHash: "x",
});
const viewer = await userRepo.insertUser({
  email: "viewer@a.test",
  name: "Viewer",
  passwordHash: "x",
});
const stranger = await userRepo.insertUser({
  email: "stranger@a.test",
  name: "Stranger",
  passwordHash: "x",
});
const org = await orgRepo.insertOrg({ name: "A", slug: "a", plan: "growth" }, owner.id);
const other = await orgRepo.insertOrg({ name: "B", slug: "b", plan: "growth" }, owner.id);
await memberRepo.insertMember(org.id, owner.id, "owner", null);
const viewerMember = await memberRepo.insertMember(org.id, viewer.id, "viewer", owner.id);
await memberRepo.insertMember(other.id, viewer.id, "admin", null);
await usageRepo.recomputeUsage(org.id);
const beforeSeats = (await usageRepo.getUsage(org.id)).seatsUsed;

const project = await projectRepo.insertProject({
  orgId: org.id,
  name: "Plat",
  slug: "platform",
  key: "PLAT",
  description: null,
  visibility: "org",
  leadId: viewer.id,
  color: "#6366f1",
  targetDate: null,
});
const otherProject = await projectRepo.insertProject({
  orgId: other.id,
  name: "Other",
  slug: "other",
  key: "OTH",
  description: null,
  visibility: "org",
  leadId: viewer.id,
  color: "#6366f1",
  targetDate: null,
});

const actor = { userId: owner.id, orgId: org.id, role: "owner" as const };
const issue = await issueService.createIssue(actor, {
  orgId: org.id,
  projectId: project.id,
  title: "Assigned work",
  description: null,
  status: "backlog",
  priority: "none",
  assigneeId: viewer.id,
  parentId: null,
  estimate: null,
  dueAt: null,
  labelIds: [],
});

await memberService.removeMember(actor, { orgId: org.id, memberId: viewerMember.id });
const removed = await memberRepo.findMember(org.id, viewer.id);
check("archived", removed?.archivedAt !== null);
check("same id", removed?.id === viewerMember.id);
check("actor null", (await memberService.resolveActor(viewer.id, org.id)) === null);
check("other org actor", (await memberService.resolveActor(viewer.id, other.id))?.role === "admin");
const after = await issueRepo.findIssueById(org.id, issue.id);
check("unassigned", after?.assigneeId === null);
const led = await projectRepo.findProjectById(org.id, project.id);
check("lead cleared", led?.leadId === null);
const otherLed = await projectRepo.findProjectById(other.id, otherProject.id);
check("other lead kept", otherLed?.leadId === viewer.id);
const seatsAfter = (await usageRepo.getUsage(org.id)).seatsUsed;
check("seat freed once", seatsAfter === beforeSeats - 1, { beforeSeats, seatsAfter });

let conflict = false;
try {
  await memberService.removeMember(actor, { orgId: org.id, memberId: viewerMember.id });
} catch (error) {
  conflict = error instanceof AlreadyArchivedError;
}
check("second remove conflict", conflict);
const seatsTwice = (await usageRepo.getUsage(org.id)).seatsUsed;
check("seat not freed twice", seatsTwice === seatsAfter, { seatsTwice, seatsAfter });

let roleConflict = false;
let roleEvents = 0;
const offRole = subscribe("member.role_changed", () => {
  roleEvents += 1;
});
try {
  await memberService.updateMemberRole(actor, {
    orgId: org.id,
    memberId: viewerMember.id,
    role: "admin",
  });
} catch (error) {
  roleConflict = error instanceof AlreadyArchivedError;
}
offRole();
check("role conflict", roleConflict);
check("no role event", roleEvents === 0);
const still = await memberRepo.findMemberById(org.id, viewerMember.id);
check("role unchanged", still?.role === "viewer");

let created = false;
try {
  await issueService.createIssue(actor, {
    orgId: org.id,
    projectId: project.id,
    title: "Should not exist",
    description: null,
    status: "backlog",
    priority: "none",
    assigneeId: viewer.id,
    parentId: null,
    estimate: null,
    dueAt: null,
    labelIds: [],
  });
  created = true;
} catch {
  created = false;
}
check("create assignee refused", !created);
const listed = await issueRepo.listIssues({ orgId: org.id, limit: 20, cursor: null });
check("no extra issue", listed.items.every((row) => row.title !== "Should not exist"));

const beforeAssign = await issueRepo.findIssueById(org.id, issue.id);
try {
  await issueService.assignIssue(actor, {
    orgId: org.id,
    issueId: issue.id,
    assigneeId: stranger.id,
  });
} catch {
  /* expected */
}
const afterAssign = await issueRepo.findIssueById(org.id, issue.id);
check("assign stranger refused", afterAssign?.assigneeId === beforeAssign?.assigneeId);

let projectCreated = false;
try {
  await projectService.createProject(actor, {
    orgId: org.id,
    name: "Bad lead",
    slug: "bad-lead",
    key: "BAD",
    description: null,
    visibility: "org",
    leadId: viewer.id,
    color: "#6366f1",
    targetDate: null,
  });
  projectCreated = true;
} catch {
  projectCreated = false;
}
check("create project refused", !projectCreated);
check(
  "project absent",
  (await projectRepo.findProjectBySlug(org.id, "bad-lead")) === null,
);

const beforeName = (await projectRepo.findProjectById(org.id, project.id))?.name;
try {
  await projectService.updateProject(actor, {
    orgId: org.id,
    projectId: project.id,
    name: "Renamed",
    leadId: viewer.id,
  });
} catch {
  /* expected */
}
check(
  "update refused wholly",
  (await projectRepo.findProjectById(org.id, project.id))?.name === beforeName,
);

const orgs = await orgRepo.listOrgsForUser(viewer.id);
check("picker omits removed", orgs.every((row) => row.id !== org.id));
check("picker keeps other", orgs.some((row) => row.id === other.id));

await preferenceRepo.upsertPreference({
  orgId: org.id,
  userId: viewer.id,
  kind: "comment_created",
  inApp: true,
  email: true,
  digestOnly: true,
});
const recipients = await listDigestRecipients(org.id);
check("not digest recipient", !recipients.includes(viewer.id));
const digest = await buildDigest(
  org.id,
  viewer.id,
  toIsoTimestamp(new Date(Date.now() - 86_400_000)),
  toIsoTimestamp(new Date()),
);
check("no digest bundle", digest === null);

const notes = await notify(org.id, "comment_created", [viewer.id, owner.id], {
  title: "New comment",
  body: "hi",
  href: "/issues/x",
  actorId: null,
});
check(
  "notify skips former",
  notes.every((row) => row.recipientId !== viewer.id) &&
    notes.some((row) => row.recipientId === owner.id),
);

const comment = await commentService.createComment(actor, {
  orgId: org.id,
  issueId: issue.id,
  body: "hey @viewer please look",
  parentId: null,
  mentionedUserIds: [viewer.id],
});
check("mention ignored", !comment.mentionedUserIds.includes(viewer.id));

const token = "d".repeat(32);
await invitationRepo.insertInvitation(
  org.id,
  { orgId: org.id, email: "viewer@a.test", role: "admin", expiresInDays: 7 },
  owner.id,
  hashToken(token),
);
let joined = 0;
const offJoin = subscribe("member.joined", () => {
  joined += 1;
});
const readmitted = await invitationService.acceptInvitation(viewer.id, { token });
offJoin();
check("same membership", readmitted.id === viewerMember.id);
check("role from invite", readmitted.role === "admin");
check("inviter from invite", readmitted.invitedBy === owner.id);
check("live again", readmitted.archivedAt === null && readmitted.status === "active");
check("join event", joined === 1);
check("can act", (await memberService.resolveActor(viewer.id, org.id))?.role === "admin");
check("listed once", (await memberRepo.countActiveMembers(org.id)) === 2);
const invites = await invitationRepo.listPendingInvitations(org.id);
check("invite spent", invites.length === 0);
const backInList = await orgRepo.listOrgsForUser(viewer.id);
check("picker shows org", backInList.some((row) => row.id === org.id));
check("other membership intact", (await memberRepo.findMember(other.id, viewer.id))?.role === "admin");

const token2 = "e".repeat(32);
await invitationRepo.insertInvitation(
  org.id,
  { orgId: org.id, email: "viewer@a.test", role: "member", expiresInDays: 7 },
  owner.id,
  hashToken(token2),
);
const seatsBeforeAccept = (await usageRepo.getUsage(org.id)).seatsUsed;
let joined2 = 0;
const off2 = subscribe("member.joined", () => {
  joined2 += 1;
});
const unchanged = await invitationService.acceptInvitation(viewer.id, { token: token2 });
off2();
check("current accept same role", unchanged.role === "admin" && unchanged.id === viewerMember.id);
check("current accept no join", joined2 === 0);
check("current accept no seat", (await usageRepo.getUsage(org.id)).seatsUsed === seatsBeforeAccept);
check("second invite spent", (await invitationRepo.listPendingInvitations(org.id)).length === 0);

await invitationService.acceptInvitation(viewer.id, { token: token2 }).catch((error: Error) => {
  check("reuse refused", /already been accepted/.test(error.message));
});

console.log(fails.length === 0 ? "ALL PASSED" : `FAILED\n${fails.join("\n")}`);
rmSync(dir, { recursive: true, force: true });
if (fails.length) process.exit(1);

